// Concrete minimal DiagnosticsProvider used for fuzzing. Implements required virtuals
// with bounded behavior and defensive checks to avoid undefined behavior.
struct FuzzDiagnosticsProvider : RTags::DiagnosticsProvider {
    size_t nUnits;
    uint32_t srcId;
    std::vector<size_t> diagCounts; // per-unit diagnostic counts (small, bounded)

    explicit FuzzDiagnosticsProvider(size_t units, uint32_t sid)
        : nUnits(units), srcId(sid), diagCounts(units, 0) {}

    size_t unitCount() const override { return nUnits; }

    size_t diagnosticCount(size_t unit) const override {
        if (unit >= nUnits) { FUZZ_BAIL(); }
        return diagCounts[unit];
    }

    CXDiagnostic diagnostic(size_t unit, size_t idx) const override {
        // Enforce bounds strictly; callers are expected to check counts first.
        if (unit >= nUnits) { FUZZ_BAIL(); }
        if (idx >= diagCounts[unit]) { FUZZ_BAIL(); }
        // We do not fabricate real CXDiagnostic objects; return a null handle which
        // is acceptable for endpoints that only touch the value.
        return nullptr;
    }

    // Map to a benign Location; set blocked=false when provided. Location lives in the global namespace.
    Location createLocation(const Path &/*file*/, unsigned int /*line*/, unsigned int /*col*/, bool *blocked = nullptr) override {
        if (blocked) *blocked = false;
        return Location();
    }

    uint32_t sourceFileId() const override { return srcId; }

    IndexDataMessage &indexDataMessage() override {
        // We cannot safely construct a valid IndexDataMessage instance here without
        // depending on external state; bail to signal unsupported access in this stub.
        FUZZ_BAIL();
    }

    CXTranslationUnit unit(size_t u) const override {
        if (u >= nUnits) { FUZZ_BAIL(); }
        // Return a null TU handle; endpoints using it do not dereference.
        return nullptr;
    }
};

